import { desc, eq, gt, sql } from 'drizzle-orm';
import type { SyncAction, SyncChange, SyncChangeset, SyncEntityType, SyncStatusResponse } from '@handoff/types/handoff-sync';
import { deleteComponentArtifacts, upsertComponentArtifacts } from './component-artifact-queries';
import { recordComponentVersion } from './component-version-queries';
import { getDb } from './index';
import {
  handoffComponents,
  handoffComponentSources,
  handoffPageChanges,
  handoffPages,
  handoffPatterns,
  syncEvents,
} from './schema';

export type InsertSyncEventInput = {
  entityType: SyncEntityType;
  entityId: string;
  action: SyncAction;
  payload?: Record<string, unknown> | null;
  userId?: string | null;
  changeType?: string | null;
};

export async function insertSyncEvent(input: InsertSyncEventInput): Promise<number | null> {
  const db = getDb();
  const [row] = await db
    .insert(syncEvents)
    .values({
      entityType: input.entityType,
      entityId: input.entityId,
      action: input.action,
      changeType: input.changeType ?? null,
      payload: input.payload ?? null,
      userId: input.userId ?? null,
    })
    .returning({ id: syncEvents.id });
  return row?.id ?? null;
}

export async function upsertComponentSources(
  componentId: string,
  sourceFiles: Record<string, string>,
  pushedByUserId: string | null
): Promise<void> {
  const db = getDb();
  for (const [filePath, content] of Object.entries(sourceFiles)) {
    await db
      .insert(handoffComponentSources)
      .values({ componentId, filePath, content, pushedByUserId, pushedAt: new Date() })
      .onConflictDoUpdate({
        target: [handoffComponentSources.componentId, handoffComponentSources.filePath],
        set: { content, pushedByUserId, pushedAt: new Date() },
      });
  }
}

export async function getLatestSyncEventId(): Promise<number> {
  const db = getDb();
  const rows = await db.select({ id: syncEvents.id }).from(syncEvents).orderBy(desc(syncEvents.id)).limit(1);
  return rows[0]?.id ?? 0;
}

/** Default page size for a bounded sync pull. */
export const DEFAULT_SYNC_PULL_LIMIT = 500;
/** Hard cap on a single sync-pull page — the change feed is append-only and payloads are large. */
export const MAX_SYNC_PULL_LIMIT = 1000;

/**
 * Fetch a bounded page of sync changes with `id > since`, ordered by id ASC.
 *
 * The feed is append-only and `sync_event.payload` holds full push payloads, so this is
 * paginated to avoid streaming the entire table in one query. `ORDER BY id ASC LIMIT n`
 * returns the smallest `n` ids above `since` — a contiguous prefix — so events are never
 * dropped or reordered; a caller simply pulls again from `nextCursor` until `hasMore` is
 * false (or lets its normal re-poll interval catch up over successive ticks).
 */
export async function fetchSyncChangesSince(since: number, limit?: number): Promise<SyncChangeset> {
  const db = getDb();
  const latest = await getLatestSyncEventId();

  const effectiveLimit = Math.min(
    Math.max(1, Math.floor(limit ?? DEFAULT_SYNC_PULL_LIMIT)),
    MAX_SYNC_PULL_LIMIT
  );

  const rows = await db
    .select()
    .from(syncEvents)
    .where(gt(syncEvents.id, since))
    .orderBy(syncEvents.id)
    .limit(effectiveLimit);

  const changes: SyncChange[] = rows.map((r) => ({
    version: r.id,
    entityType: r.entityType as SyncEntityType,
    entityId: r.entityId,
    action: r.action as SyncAction,
    updatedAt: (r.createdAt instanceof Date ? r.createdAt : new Date(r.createdAt as string)).toISOString(),
    data: (r.payload as SyncChange['data']) ?? null,
  }));

  // Highest id actually delivered in this page (the page is a contiguous prefix from `since`).
  const nextCursor = changes.length > 0 ? changes[changes.length - 1].version : since;
  const hasMore = nextCursor < latest;

  // `version` is the cursor a client saves as its next pull baseline. When the page is
  // bounded it MUST equal `nextCursor` — never the DB-wide `latest` — or a client that
  // advances by `version` alone would silently skip the undelivered tail. When fully
  // drained it equals `latest` (preserving the original unbounded behavior exactly).
  const version = hasMore ? nextCursor : latest;

  return { version, changes, hasMore, nextCursor };
}

export async function getSyncStatus(): Promise<SyncStatusResponse> {
  const db = getDb();
  const latestVersion = await getLatestSyncEventId();

  const [comp] = await db.select({ c: sql<number>`count(*)` }).from(handoffComponents);
  const [pat] = await db.select({ c: sql<number>`count(*)` }).from(handoffPatterns);
  const [pg] = await db.select({ c: sql<number>`count(*)` }).from(handoffPages);
  const [ev] = await db.select({ c: sql<number>`count(*)` }).from(syncEvents);

  return {
    latestVersion,
    counts: {
      components: comp?.c ?? 0,
      patterns: pat?.c ?? 0,
      pages: pg?.c ?? 0,
      syncEvents: ev?.c ?? 0,
    },
  };
}

/** Apply one uploaded change from CLI and append a sync_event (same shape as remote edits). */
export async function applyUploadedChange(input: {
  entityType: SyncEntityType;
  entityId: string;
  action: SyncAction;
  data?: Record<string, unknown> | null;
  userId?: string | null;
}): Promise<void> {
  const db = getDb();

  const { entityType, entityId, action, data, userId } = input;

  if (entityType === 'component') {
    if (action === 'delete') {
      await deleteComponentArtifacts(entityId);
      await db.delete(handoffComponents).where(eq(handoffComponents.id, entityId));
      await insertSyncEvent({
        entityType,
        entityId,
        action: 'delete',
        payload: { id: entityId },
        userId,
      });
      return;
    }
    const d = (data ?? {}) as Record<string, unknown>;
    const dataPayload =
      d.data && typeof d.data === 'object' && !Array.isArray(d.data)
        ? ({ ...(d.data as Record<string, unknown>) } as Record<string, unknown>)
        : ({ ...d } as Record<string, unknown>);
    if (d.handoffConfig && typeof d.handoffConfig === 'object') {
      dataPayload.handoffConfig = d.handoffConfig;
    }
    // Slot capability record from the build-time probe: which encodings each ReactNode slot was
    // measured to accept. Carried in `data` rather than its own column deliberately — adding a column
    // to a hot table breaks every read of it on any deployment where the migration has not landed yet,
    // which took the generation queue down earlier today. `data` already carries build output.
    if (d.capabilities && typeof d.capabilities === 'object') {
      dataPayload.capabilities = d.capabilities;
    }
    const row = {
      id: String(d.id ?? entityId),
      path: d.path != null ? String(d.path) : null,
      title: String(d.title ?? dataPayload.title ?? entityId),
      description: d.description != null ? String(d.description) : String(dataPayload.description ?? ''),
      group: d.group != null ? String(d.group) : String(dataPayload.group ?? ''),
      image: d.image != null ? String(d.image) : dataPayload.image != null ? String(dataPayload.image) : null,
      type: d.type != null ? String(d.type) : String(dataPayload.type ?? 'element'),
      properties: (d.properties as object) ?? (dataPayload.properties as object) ?? null,
      previews: (d.previews as object) ?? (dataPayload.previews as object) ?? null,
      data: dataPayload,
      source: typeof d.source === 'string' && d.source.length > 0 ? String(d.source) : 'sync',
      updatedAt: new Date(),
    };
    await db
      .insert(handoffComponents)
      .values({
        ...row,
        createdAt: new Date(),
      })
      .onConflictDoUpdate({
        target: handoffComponents.id,
        set: {
          path: row.path,
          title: row.title,
          description: row.description,
          group: row.group,
          image: row.image,
          type: row.type,
          properties: row.properties,
          previews: row.previews,
          data: row.data,
          source: row.source,
          updatedAt: row.updatedAt,
        },
      });
    const incomingArtifactFilenames: string[] = [];
    if (d.buildArtifacts && typeof d.buildArtifacts === 'object' && !Array.isArray(d.buildArtifacts)) {
      await upsertComponentArtifacts(row.id, d.buildArtifacts as Record<string, string>);
      incomingArtifactFilenames.push(...Object.keys(d.buildArtifacts as Record<string, string>).sort());
    }
    const incomingSourceFiles: Record<string, string> = {};
    if (d.sourceFiles && typeof d.sourceFiles === 'object' && !Array.isArray(d.sourceFiles)) {
      Object.assign(incomingSourceFiles, d.sourceFiles as Record<string, string>);
      await upsertComponentSources(row.id, incomingSourceFiles, userId ?? null);
    }

    // Record a version snapshot if anything changed from the previous push.
    // Fire-and-forget: a version failure never surfaces to the push caller.
    recordComponentVersion({
      componentId: row.id,
      userId: userId ?? null,
      trigger: typeof d.trigger === 'string' ? d.trigger : 'push',
      newRow: {
        title: row.title,
        description: row.description ?? null,
        group: row.group ?? null,
        path: row.path ?? null,
        type: row.type ?? null,
        properties: row.properties ?? null,
        previews: row.previews ?? null,
        data: row.data ?? null,
      },
      incomingSourceFiles,
      incomingArtifactFilenames,
      message: typeof d.message === 'string' ? d.message : null,
    }).catch(() => {});

    await insertSyncEvent({
      entityType,
      entityId: row.id,
      action: action === 'create' ? 'create' : 'update',
      payload: d,
      userId,
      changeType: typeof d.changeType === 'string' ? d.changeType : undefined,
    });
    return;
  }

  if (entityType === 'pattern') {
    if (action === 'delete') {
      await db.delete(handoffPatterns).where(eq(handoffPatterns.id, entityId));
      await insertSyncEvent({
        entityType,
        entityId,
        action: 'delete',
        payload: { id: entityId },
        userId,
      });
      return;
    }
    const d = (data ?? {}) as Record<string, unknown>;
    const row = {
      id: String(d.id ?? entityId),
      path: d.path != null ? String(d.path) : null,
      title: String(d.title ?? entityId),
      description: d.description != null ? String(d.description) : '',
      group: d.group != null ? String(d.group) : '',
      tags: (d.tags as object) ?? null,
      components: (d.components as object) ?? null,
      data: (d.data as object) ?? (d as object),
      updatedAt: new Date(),
    };
    await db
      .insert(handoffPatterns)
      .values({
        ...row,
        createdAt: new Date(),
      })
      .onConflictDoUpdate({
        target: handoffPatterns.id,
        set: {
          path: row.path,
          title: row.title,
          description: row.description,
          group: row.group,
          tags: row.tags,
          components: row.components,
          data: row.data,
          updatedAt: row.updatedAt,
        },
      });
    await insertSyncEvent({
      entityType,
      entityId: row.id,
      action: action === 'create' ? 'create' : 'update',
      payload: d,
      userId,
    });
    return;
  }

  if (entityType === 'page') {
    if (action === 'delete') {
      // Read the existing page for the change record before deleting
      const [existing] = await db
        .select({ frontmatter: handoffPages.frontmatter, markdown: handoffPages.markdown })
        .from(handoffPages)
        .where(eq(handoffPages.slug, entityId))
        .limit(1);
      const existingFm = (existing?.frontmatter ?? {}) as Record<string, unknown>;
      await db.delete(handoffPages).where(eq(handoffPages.slug, entityId));
      // Record the page change
      await db.insert(handoffPageChanges).values({
        slug: entityId,
        action: 'deleted',
        pushedByUserId: userId ?? null,
        trigger: 'push',
        titleBefore: existingFm.title != null ? String(existingFm.title) : null,
        titleAfter: null,
        markdownLengthBefore: existing?.markdown != null ? existing.markdown.length : null,
        markdownLengthAfter: null,
        message: data && typeof (data as Record<string, unknown>).message === 'string'
          ? String((data as Record<string, unknown>).message)
          : null,
      }).catch(() => {});
      await insertSyncEvent({
        entityType,
        entityId,
        action: 'delete',
        payload: { slug: entityId },
        userId,
      });
      return;
    }
    const d = (data ?? {}) as Record<string, unknown>;
    const slug = String(d.slug ?? entityId);
    const frontmatter = (d.frontmatter as Record<string, unknown>) ?? {};
    const markdown = String(d.markdown ?? '');

    // Read the existing page (if any) to determine created vs updated and compute diff
    const [existing] = await db
      .select({ frontmatter: handoffPages.frontmatter, markdown: handoffPages.markdown })
      .from(handoffPages)
      .where(eq(handoffPages.slug, slug))
      .limit(1);
    const isNew = !existing;
    const existingFm = (existing?.frontmatter ?? {}) as Record<string, unknown>;

    await db
      .insert(handoffPages)
      .values({
        slug,
        frontmatter,
        markdown,
        updatedAt: new Date(),
      })
      .onConflictDoUpdate({
        target: handoffPages.slug,
        set: {
          frontmatter,
          markdown,
          updatedAt: new Date(),
        },
      });

    // Record the page change (fire-and-forget — never surface to push caller)
    const trigger = typeof d.trigger === 'string' ? d.trigger : 'push';
    db.insert(handoffPageChanges).values({
      slug,
      action: isNew ? 'created' : 'updated',
      pushedByUserId: userId ?? null,
      trigger,
      titleBefore: isNew ? null : (existingFm.title != null ? String(existingFm.title) : null),
      titleAfter: frontmatter.title != null ? String(frontmatter.title) : null,
      markdownLengthBefore: isNew ? null : (existing?.markdown != null ? existing.markdown.length : null),
      markdownLengthAfter: markdown.length,
      message: typeof d.message === 'string' ? d.message : null,
    }).catch(() => {});

    await insertSyncEvent({
      entityType,
      entityId: slug,
      action: action === 'create' ? 'create' : 'update',
      payload: { slug, frontmatter, markdown },
      userId,
    });
    return;
  }
}
